        [`${full}.delta.json`, `${full}.delta.json.sig`, raw, `${raw}.sig`, `mesh-talk-patch_v0.1.5_${platform}_from-v0.1.4.zst`])];
      for (const name of standalone) files.set(name, Buffer.from(`standalone ${name}`));
