      assert.deepEqual(execFileSync("unzip", ["-Z1", archive], { encoding: "utf8" }).trim().split(/\r?\n/).sort(), members.sort(), "repackaging must discard stale ZIP entries");
    } finally {
      rmSync(root, { recursive: true, force: true });
    }
  }
});

